class OrderCache:
    def __init__(self):
        self.cache = {}

    def get_or_load(self, order_id, loader):
        if order_id in self.cache:
            return self.cache[order_id]
        value = loader(order_id)
        self.cache[order_id] = value
        return value

    def clear(self):
        self.cache = {}

    def stats(self):
        return {"size": len(self.cache)}
