import json, os

def load_config(path="config.json"):
    try:
        with open(path) as f:
            cfg = json.load(f)
        if "port" not in cfg:
            cfg["port"] = 80
        if os.environ.get("CONFIG_OVERRIDE"):
            cfg.update(json.loads(os.environ["CONFIG_OVERRIDE"]))
